/*
 * A010155  Continued fraction for sqrt(77).
 * https://oeis.org/A010155
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr
 * Formula:   not stated
 * Range:     u8 none, u16 n <= 9610, u32 n <= 9610, u64 n <= 9610,
 *            u128 n <= 9610, big any n
 * Helpers:   floor_sqrt
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Continued fraction for sqrt(77)
   a(0) = 8 and the repeating period is [1,3,2,3,1,16]   */
/* The sequence is generated by the classic continued‑fraction
   algorithm for square roots. */

#include <stdbool.h>
#include <stddef.h>
#include "../utils/floor_sqrt.h"   /* provides floor_sqrt(seq_t) */

static seq_t period[16];        /* period length is 6, buffer is larger */
static size_t period_len = 0U;
static bool period_ready = false;
static seq_t a0 = 0U;

/* Initialise a0 and the period of the continued fraction for sqrt(77) */
static void init_period(void)
{
    /* The integer part of sqrt(77) */
    a0 = floor_sqrt( (seq_t)77 );

    seq_t m = 0U;
    seq_t d = 1U;
    seq_t a = a0;
    size_t idx = 0U;

    /* Classic algorithm for the periodic part */
    while (true) {
        m = d * a - m;
        d = ((seq_t)77 - m * m) / d;
        a = (a0 + m) / d;
        period[idx++] = a;
        if (a == 2U * a0)   /* period ends when a == 2*a0 */
            break;
    }
    period_len = idx;
    period_ready = true;
}

/* Sequence generator */
seq_t a(idx_t n)
{
    if (!period_ready)
        init_period();

    if (n == 0)
        return a0;

    /* Use 0‑based indexing into the period array */
    size_t period_index = (size_t)((n - 1U) % period_len);
    return period[period_index];
}
